--
-- Name: v_person; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_person AS
 SELECT p.person_id,
    pp.personal_number,
    concat_ws(' '::text, p.last_name, p.first_name, p.patronymic) AS fio,
    s.rank_name,
    s.position_name,
    s.unit_code,
    u.short_name AS unit,
    u.full_name AS unit_full,
    u.country,
    pp.birth_date,
    (date_part('year'::text, age((CURRENT_DATE)::timestamp with time zone, (pp.birth_date)::timestamp with time zone)))::integer AS age,
    pp.sex,
    pp.nationality,
    pp.birthplace,
    pp.height_cm,
    pp.weight_kg,
    round(((pp.weight_kg)::numeric / (((pp.height_cm)::numeric / 100.0) ^ (2)::numeric)), 1) AS bmi,
    pp.clothing_size,
    pp.shoe_size,
    pp.head_size,
    pp.helmet_size,
    pp.glove_size,
    pp.blood_group,
    pp.fitness_category,
    pp.allergies,
    pp.last_med_exam,
    pp.service_type,
    pp.service_start,
    pp.contract_end,
    pp.education,
    pp.marital_status,
    pp.children,
    ca.vehicle_sname AS vehicle,
    v.tactical_no AS vehicle_tactical_no,
    ca.seat,
    pp.iin
   FROM (((((mil_core.person p
     JOIN mil_core.person_profile pp USING (person_id))
     JOIN mil_core.staff_position s USING (person_id))
     JOIN mil_core.unit u USING (unit_code))
     LEFT JOIN mil_core.crew_assignment ca USING (staff_id))
     LEFT JOIN mil_core.vehicle v ON ((v.vehicle_id = ca.vehicle_id)));


