    CONSTRAINT supply_request_qty_check CHECK ((qty > (0)::numeric)),
    CONSTRAINT supply_request_status_check CHECK ((status = ANY (ARRAY['создана'::text, 'согласована'::text, 'выполнена'::text, 'отклонена'::text])))
);


