COMMENT ON TABLE mil_core.unit_property IS 'Групповое имущество подразделения (палатки, аптечки взвода, комплекты санинструктора и т.п.), условные нормы';


--
-- Name: warehouse; Type: TABLE; Schema: mil_core; Owner: -
--

CREATE TABLE mil_core.warehouse (
    warehouse_id integer NOT NULL,
    warehouse_name text NOT NULL,
    kind text NOT NULL,
    unit_code text NOT NULL,
    serves_unit_code text NOT NULL,
    parent_warehouse_id integer,
    capacity_note text,
    CONSTRAINT warehouse_kind_check CHECK ((kind = ANY (ARRAY['ГСМ'::text, 'РАВ'::text, 'вещевой'::text, 'продовольственный'::text, 'медицинский'::text, 'вышестоящий'::text])))
);


--
-- Name: TABLE warehouse; Type: COMMENT; Schema: mil_core; Owner: -
--

COMMENT ON TABLE mil_core.warehouse IS 'Склады: вид, кто содержит, кого обеспечивает, вышестоящий склад для заявок';


--
-- Name: v_stock_balance; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_stock_balance AS
 SELECT w.warehouse_id,
    w.warehouse_name,
    w.kind,
    m.item_sname,
    i.item_name,
    m.size,
    sum(m.qty) AS balance,
    i.unit_measure,
    max(m.moved_at) AS last_movement
   FROM ((mil_core.stock_movement m
     JOIN mil_core.warehouse w USING (warehouse_id))
     JOIN mil_core.item i USING (item_sname))
  GROUP BY w.warehouse_id, w.warehouse_name, w.kind, m.item_sname, i.item_name, m.size, i.unit_measure;


--
-- Name: VIEW v_stock_balance; Type: COMMENT; Schema: mil_core; Owner: -
--

COMMENT ON VIEW mil_core.v_stock_balance IS 'Текущие остатки на складах';


--
-- Name: v_fuel_overview; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_fuel_overview AS
 SELECT product,
    place,
    sum(litres) AS litres
   FROM ( SELECT vehicle.fuel_product AS product,
            'в баках техники'::text AS place,
            vehicle.fuel_level_l AS litres
           FROM mil_core.vehicle
          WHERE (vehicle.fuel_product IS NOT NULL)
        UNION ALL
         SELECT vehicle.cargo_product,
            'на топливозаправщиках'::text AS text,
            vehicle.cargo_level_l
           FROM mil_core.vehicle
          WHERE (vehicle.cargo_product IS NOT NULL)
        UNION ALL
         SELECT v_stock_balance.item_sname,
            v_stock_balance.warehouse_name,
            v_stock_balance.balance
           FROM mil_core.v_stock_balance
          WHERE ((v_stock_balance.kind = ANY (ARRAY['ГСМ'::text, 'вышестоящий'::text])) AND (v_stock_balance.item_sname IN ( SELECT item.item_sname
                   FROM mil_core.item
                  WHERE (item.category = 'Горючее и смазочные материалы'::text))))) x
  GROUP BY product, place;


--
-- Name: VIEW v_fuel_overview; Type: COMMENT; Schema: mil_core; Owner: -
--

COMMENT ON VIEW mil_core.v_fuel_overview IS 'Сколько топлива какого вида: в баках, на топливозаправщиках, на складах';


--
-- Name: v_item_fuel; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_item_fuel AS
 SELECT item_sname,
    COALESCE(( SELECT s.value_num
           FROM mil_core.item_spec s
          WHERE ((s.item_sname = i.item_sname) AND (s.param_name = 'Топливо всего (внутр.+наружн.)'::text))
          ORDER BY s.confidence
         LIMIT 1), ( SELECT s.value_num
           FROM mil_core.item_spec s
          WHERE ((s.item_sname = i.item_sname) AND (s.param_name = 'Ёмкость топливных баков (основных)'::text))
          ORDER BY s.confidence
         LIMIT 1)) AS refill_l,
    ( SELECT s.value_text
           FROM mil_core.item_spec s
          WHERE ((s.item_sname = i.item_sname) AND (s.param_name = 'Вид топлива'::text))
          ORDER BY s.confidence
         LIMIT 1) AS fuel_type
   FROM mil_core.item i;


--
-- Name: v_person_issue; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_person_issue AS
 SELECT i.person_id,
    concat_ws(' '::text, p.last_name, p.first_name, p.patronymic) AS fio,
    i.item_sname,
    it.item_name,
    it.category,
    i.qty,
    it.unit_measure,
    i.size,
    i.serial_no,
    i.issued_on,
    i.wear_until,
    k.kit_name
   FROM (((mil_core.person_issue i
     JOIN mil_core.person p USING (person_id))
     JOIN mil_core.item it USING (item_sname))
     LEFT JOIN mil_core.kit k USING (kit_code));


--
-- Name: v_stock_vs_norm; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_stock_vs_norm AS
 SELECT w.warehouse_id,
    w.warehouse_name,
    n.item_sname,
    i.item_name,
    n.size,
    n.norm_qty,
    COALESCE(b.balance, (0)::numeric) AS balance,
    GREATEST((n.norm_qty - COALESCE(b.balance, (0)::numeric)), (0)::numeric) AS deficit,
    round((((100)::numeric * COALESCE(b.balance, (0)::numeric)) / NULLIF(n.norm_qty, (0)::numeric))) AS provision_pct,
    i.unit_measure,
    n.basis
   FROM (((mil_core.stock_norm n
     JOIN mil_core.warehouse w USING (warehouse_id))
     JOIN mil_core.item i USING (item_sname))
     LEFT JOIN mil_core.v_stock_balance b ON (((b.warehouse_id = n.warehouse_id) AND (b.item_sname = n.item_sname) AND (b.size = n.size))));


--
-- Name: VIEW v_stock_vs_norm; Type: COMMENT; Schema: mil_core; Owner: -
--

COMMENT ON VIEW mil_core.v_stock_vs_norm IS 'Остаток против нормы: дефицит и процент обеспеченности';


--
-- Name: v_supply_request; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_supply_request AS
 SELECT r.request_id,
    r.created_at,
    r.requester_unit,
    u.short_name AS requester,
    w.warehouse_name AS to_warehouse,
    r.item_sname,
    i.item_name,
    r.size,
    r.qty,
    i.unit_measure,
    r.status,
    r.reason,
    r.created_by
   FROM (((mil_core.supply_request r
     JOIN mil_core.unit u ON ((u.unit_code = r.requester_unit)))
     JOIN mil_core.warehouse w ON ((w.warehouse_id = r.to_warehouse_id)))
     JOIN mil_core.item i USING (item_sname));


--
-- Name: v_unit_tree; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_unit_tree AS
 SELECT p.unit_code AS root_code,
    c.unit_code
   FROM (mil_core.unit p
     JOIN mil_core.unit c ON ((c.unit_code ~~ (p.unit_code || '%'::text))));


--
-- Name: v_unit_holding; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_unit_holding AS
 SELECT t.root_code AS unit_code,
    h.item_sname,
    sum(h.qty) AS qty
   FROM (mil_core.v_unit_tree t
     JOIN mil_core.holding h ON ((h.unit_code = t.unit_code)))
  GROUP BY t.root_code, h.item_sname;


--
-- Name: v_unit_need; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_unit_need AS
 SELECT t.root_code AS unit_code,
    ki.item_sname,
    sum(ki.qty) AS qty
   FROM (((mil_core.v_unit_tree t
     JOIN mil_core.staff_position s ON ((s.unit_code = t.unit_code)))
     JOIN mil_core.position_kit pk USING (position_name))
     JOIN mil_core.kit_item ki USING (kit_code))
  GROUP BY t.root_code, ki.item_sname;


--
-- Name: vehicle_ammo_load; Type: TABLE; Schema: mil_core; Owner: -
--

CREATE TABLE mil_core.vehicle_ammo_load (
    vehicle_sname text NOT NULL,
    ammo_sname text NOT NULL,
    qty integer NOT NULL,
    confidence character(1) NOT NULL,
    CONSTRAINT vehicle_ammo_load_qty_check CHECK ((qty > 0))
);


--
-- Name: v_unit_ammo; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_unit_ammo AS
 SELECT unit_code,
    ammo_sname,
    sum(personal) AS personal_load,
    sum(vehicle) AS vehicle_load,
    sum((personal + vehicle)) AS total
   FROM ( SELECT n.unit_code,
            n.item_sname AS ammo_sname,
            n.qty AS personal,
            0 AS vehicle
           FROM (mil_core.v_unit_need n
             JOIN mil_core.item i USING (item_sname))
          WHERE (i.category = 'Боеприпасы'::text)
        UNION ALL
         SELECT h.unit_code,
            a.ammo_sname,
            0,
            (h.qty * a.qty)
           FROM (mil_core.v_unit_holding h
             JOIN mil_core.vehicle_ammo_load a ON ((a.vehicle_sname = h.item_sname)))) x
  GROUP BY unit_code, ammo_sname;


--
-- Name: v_unit_fuel; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_unit_fuel AS
 SELECT h.unit_code,
    COALESCE(f.fuel_type, 'вид не указан'::text) AS fuel_type,
    sum(h.qty) AS vehicles,
    sum(h.qty) FILTER (WHERE (f.refill_l IS NOT NULL)) AS vehicles_with_data,
    sum(((h.qty)::numeric * COALESCE(f.refill_l, (0)::numeric))) AS fuel_one_refill_l
   FROM ((mil_core.v_unit_holding h
     JOIN mil_core.v_item_fuel f USING (item_sname))
     JOIN mil_core.item i USING (item_sname))
  WHERE ((i.category = ANY (ARRAY['Бронетанковое вооружение и техника'::text, 'Автомобильная техника и прицепы'::text, 'Инженерная техника'::text])) OR ((i.category = 'Ракетно-артиллерийское вооружение'::text) AND (EXISTS ( SELECT 1
           FROM mil_core.item_spec s
          WHERE (s.item_sname = i.item_sname)))) OR (f.refill_l IS NOT NULL))
  GROUP BY h.unit_code, COALESCE(f.fuel_type, 'вид не указан'::text);


--
-- Name: v_vehicle; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_vehicle AS
 SELECT v.vehicle_id,
    v.item_sname,
    i.item_name,
    v.unit_code,
    u.short_name AS unit,
    v.vehicle_no,
    v.tactical_no,
    v.factory_no,
    v.year_made,
    v.mileage_km,
    v.motor_hours,
    v.status,
    v.fuel_product,
    f.refill_l AS tank_capacity_l,
    v.fuel_level_l,
        CASE
            WHEN (f.refill_l > (0)::numeric) THEN round((((100)::numeric * v.fuel_level_l) / f.refill_l))
            ELSE NULL::numeric
        END AS fuel_pct,
    (f.refill_l - v.fuel_level_l) AS to_full_l,
    v.cargo_product,
    v.cargo_level_l,
    ( SELECT count(*) AS count
           FROM mil_core.crew_assignment c
          WHERE ((c.vehicle_id = v.vehicle_id) AND (c.seat = 'экипаж'::text))) AS crew_on_board,
    ( SELECT count(*) AS count
           FROM mil_core.crew_assignment c
          WHERE ((c.vehicle_id = v.vehicle_id) AND (c.seat = 'десант'::text))) AS troops_on_board
   FROM (((mil_core.vehicle v
     JOIN mil_core.item i USING (item_sname))
     JOIN mil_core.unit u USING (unit_code))
     LEFT JOIN mil_core.v_item_fuel f USING (item_sname));


--
-- Name: v_unit_fuel_state; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_unit_fuel_state AS
 SELECT t.root_code AS unit_code,
    v.fuel_product,
    count(*) AS vehicles,
    sum(v.tank_capacity_l) AS capacity_l,
    sum(v.fuel_level_l) AS in_tanks_l,
    sum(v.to_full_l) AS to_full_l,
    sum(
        CASE
            WHEN (v.cargo_product = v.fuel_product) THEN v.cargo_level_l
            ELSE (0)::numeric
        END) AS on_tankers_same_product_l
   FROM (mil_core.v_unit_tree t
     JOIN mil_core.v_vehicle v ON ((v.unit_code = t.unit_code)))
  WHERE (v.fuel_product IS NOT NULL)
  GROUP BY t.root_code, v.fuel_product;


--
-- Name: VIEW v_unit_fuel_state; Type: COMMENT; Schema: mil_core; Owner: -
--

COMMENT ON VIEW mil_core.v_unit_fuel_state IS 'По подразделению с подчинёнными: ёмкость баков, налито, сколько до полной, на ТЗ';


--
-- Name: v_unit_personnel; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_unit_personnel AS
 SELECT t.root_code AS unit_code,
    sum(u.personnel_own) AS personnel,
    sum(u.personnel_own_estimated) AS personnel_estimated
   FROM (mil_core.v_unit_tree t
     JOIN mil_core.unit u ON ((u.unit_code = t.unit_code)))
  GROUP BY t.root_code;


--
-- Name: v_unit_property_total; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_unit_property_total AS
 SELECT t.root_code AS unit_code,
    p.item_sname,
    sum(p.qty) AS qty
   FROM (mil_core.v_unit_tree t
     JOIN mil_core.unit_property p ON ((p.unit_code = t.unit_code)))
  GROUP BY t.root_code, p.item_sname;


--
-- Name: v_unit_staff_by_category; Type: VIEW; Schema: mil_core; Owner: -
--

CREATE VIEW mil_core.v_unit_staff_by_category AS
 SELECT t.root_code AS unit_code,
    count(*) AS staff_total,
    count(*) FILTER (WHERE (r.category = 'офицеры'::text)) AS officers,
    count(*) FILTER (WHERE ((r.category = 'сержанты'::text) AND (r.rank_name = ANY (ARRAY['сержант третьего класса'::text, 'сержант второго класса'::text, 'сержант первого класса'::text, 'штаб-сержант'::text, 'мастер-сержант'::text])))) AS prof_sergeants,
    count(*) FILTER (WHERE (r.category = 'сержанты'::text)) AS sergeants,
    count(*) FILTER (WHERE (r.category = 'солдаты'::text)) AS soldiers
   FROM ((mil_core.v_unit_tree t
     JOIN mil_core.staff_position s ON ((s.unit_code = t.unit_code)))
     JOIN mil_core.rank r USING (rank_name))
  GROUP BY t.root_code;


--
-- Name: vehicle_crew_role; Type: TABLE; Schema: mil_core; Owner: -
