CREATE TABLE mil_core.vehicle_crew_role (
    vehicle_sname text NOT NULL,
    role_name text NOT NULL,
    qty integer NOT NULL,
    seat text NOT NULL,
    CONSTRAINT vehicle_crew_role_qty_check CHECK ((qty > 0)),
    CONSTRAINT vehicle_crew_role_seat_check CHECK ((seat = ANY (ARRAY['экипаж'::text, 'десант'::text])))
);


